import sys
import optax
sys.path.append('storage/noema/submissions')
from dual_path_hybrid_motif_heads_regcal import build_network as core_build_network

BASE_SEED = 42
BATCH_SIZE = 64

def _define_hyperparameters():
    return {
        "learning_rate": 0.001,
        "weight_decay": 0.01,
        "head_dropout": 0.05,
    }

def create_network(hparams):
    # Extract d_output and task_type from hparams (added by the training system)
    d_output = hparams.get('d_output', 1)
    task_type = hparams.get('task_type', 'regression')

    # The lineage file has build_network, not create_network
    # build_network requires d_output, task_type, and hparams
    return core_build_network(d_output=d_output, task_type=task_type, hparams=hparams)

def create_optimizer(learning_rate: float = 0.001):
    return optax.chain(
        optax.clip_by_global_norm(0.50),
        optax.adamw(learning_rate=learning_rate, b1=0.85, b2=0.99, weight_decay=0.01),
    )

def complete(params, opt_state, trial_data):
    ds = trial_data.get('dataset'); vm = trial_data.get('val_metric')
    print(f"[Complete] {ds} val_metric={vm}")
